SELECT p.id AS position_id, c.symbol, c.open_time, c.close_time, c.open_price, c.high_price, c.low_price, c.close_price, c.volume, c.number_of_trades, c.closed, c.ingestion_source FROM crypto_ai.paper_position p JOIN crypto_ai.candle c ON c.symbol = p.symbol AND c.interval_code = '1m' AND c.open_time BETWEEN p.opened_at - INTERVAL 4 MINUTE AND p.closed_at + INTERVAL 2 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, c.open_time LIMIT 200;